-- 地块统一成格子：已卖出的旧地块换成最近的同类格子，编号 = 格子编号
DROP INDEX IF EXISTS plots_owner;
CREATE INDEX IF NOT EXISTS plots_owner2 ON plots(owner);
DELETE FROM plots WHERE owner IS NULL;
UPDATE plots SET id = id + 1000000;
UPDATE plots SET id = CASE id - 1000000 WHEN 0 THEN 6146 WHEN 1 THEN 6147 WHEN 2 THEN 6244 WHEN 3 THEN 6246 WHEN 4 THEN 6151 WHEN 5 THEN 6153 WHEN 6 THEN 6337 WHEN 7 THEN 6339 WHEN 8 THEN 6340 WHEN 9 THEN 6342 WHEN 10 THEN 6343 WHEN 11 THEN 6345 WHEN 12 THEN 6433 WHEN 13 THEN 6435 WHEN 14 THEN 6436 WHEN 15 THEN 6438 WHEN 16 THEN 6439 WHEN 17 THEN 6441 WHEN 18 THEN 6434 WHEN 19 THEN 6338 WHEN 20 THEN 6437 WHEN 21 THEN 6341 WHEN 22 THEN 6440 WHEN 23 THEN 6344 END WHERE id >= 1000000;
UPDATE saves SET data = json_set(data, '$.ownPlot', CASE json_extract(data, '$.ownPlot') WHEN 0 THEN 6146 WHEN 1 THEN 6147 WHEN 2 THEN 6244 WHEN 3 THEN 6246 WHEN 4 THEN 6151 WHEN 5 THEN 6153 WHEN 6 THEN 6337 WHEN 7 THEN 6339 WHEN 8 THEN 6340 WHEN 9 THEN 6342 WHEN 10 THEN 6343 WHEN 11 THEN 6345 WHEN 12 THEN 6433 WHEN 13 THEN 6435 WHEN 14 THEN 6436 WHEN 15 THEN 6438 WHEN 16 THEN 6439 WHEN 17 THEN 6441 WHEN 18 THEN 6434 WHEN 19 THEN 6338 WHEN 20 THEN 6437 WHEN 21 THEN 6341 WHEN 22 THEN 6440 WHEN 23 THEN 6344 END, '$.houses', json_object(CAST(CASE json_extract(data, '$.ownPlot') WHEN 0 THEN 6146 WHEN 1 THEN 6147 WHEN 2 THEN 6244 WHEN 3 THEN 6246 WHEN 4 THEN 6151 WHEN 5 THEN 6153 WHEN 6 THEN 6337 WHEN 7 THEN 6339 WHEN 8 THEN 6340 WHEN 9 THEN 6342 WHEN 10 THEN 6343 WHEN 11 THEN 6345 WHEN 12 THEN 6433 WHEN 13 THEN 6435 WHEN 14 THEN 6436 WHEN 15 THEN 6438 WHEN 16 THEN 6439 WHEN 17 THEN 6441 WHEN 18 THEN 6434 WHEN 19 THEN 6338 WHEN 20 THEN 6437 WHEN 21 THEN 6341 WHEN 22 THEN 6440 WHEN 23 THEN 6344 END AS TEXT), 'sjxc'), '$.homeAt', 'sjxc') WHERE json_extract(data, '$.ownPlot') IS NOT NULL;
DELETE FROM estate_reports;
DELETE FROM estate_staff WHERE estate_id IN (SELECT id FROM estates WHERE owner IS NULL);
DELETE FROM estates WHERE owner IS NULL;
UPDATE estates SET id = id + 1000000;
UPDATE estates SET id = CASE id - 1000000 WHEN 0 THEN 2931 WHEN 1 THEN 2725 WHEN 2 THEN 3687 WHEN 3 THEN 3098 WHEN 4 THEN 4536 WHEN 5 THEN 1489 WHEN 6 THEN 5320 WHEN 7 THEN 3519 WHEN 8 THEN 3945 WHEN 9 THEN 3610 WHEN 10 THEN 4042 WHEN 11 THEN 3998 END WHERE id >= 1000000;
UPDATE estate_staff SET estate_id = CASE estate_id WHEN 0 THEN 2931 WHEN 1 THEN 2725 WHEN 2 THEN 3687 WHEN 3 THEN 3098 WHEN 4 THEN 4536 WHEN 5 THEN 1489 WHEN 6 THEN 5320 WHEN 7 THEN 3519 WHEN 8 THEN 3945 WHEN 9 THEN 3610 WHEN 10 THEN 4042 WHEN 11 THEN 3998 END;
